        if (VIS4 && det_k >= 0 && (cell & 3) != det_k) continue; /* VIS4: each empty cell is rescored once per cycle */
        if (!VIS4 && DET_PERIOD > 1 && ((cell + frame_no) % DET_PERIOD) != 0) continue; /* approx arm: each empty cell is rescored every DET_PERIOD frames */
        if (DET_COOL && det_until[cell] > frame_no) continue;
        if (nscored >= (frame_no < DET_T0 ? DET_BUDGET0 : DET_BUDGET) || (GOV && nscored >= gov_cells)) { stop_cell = cell; break; }
        nscored++;
