                        v128_t gxv = wasm_i16x8_sub(wasm_u16x8_load8x8(p + xx + 1), wasm_u16x8_load8x8(p + xx - 1));
                        v128_t gyv = wasm_i16x8_sub(wasm_u16x8_load8x8(p + xx + IMG_W), wasm_u16x8_load8x8(p + xx - IMG_W));
